from pathlib import Path
P=Path(__file__).parent/'meridian-deck/elements'
f=P/'radar/element.css';s=f.read_text()+'''\n.radar[data-el="meridian-deck-radar"]::before{inset:auto;left:50%;top:50%;width:min(68cqw,68cqh);height:min(68cqw,68cqh);translate:-50% -50%;border-radius:999px}.radar[data-el="meridian-deck-radar"]>.axis{inset:auto;left:50%;top:50%;translate:-50% -50%;width:min(84cqw,84cqh);height:min(84cqw,84cqh)}.radar[data-el="meridian-deck-radar"]>.axis::before{width:40.5%}.radar[data-el="meridian-deck-radar"]>.axis>.name{left:calc(50% + cos(-90deg + var(--meridian-deck-i)*360deg/var(--n))*50%);top:calc(50% + sin(-90deg + var(--meridian-deck-i)*360deg/var(--n))*50%)}.radar[data-el="meridian-deck-radar"]>.series{inset:0;translate:0}.radar[data-el="meridian-deck-radar"]>.series::before{inset:auto;left:50%;top:50%;translate:-50% -50%;width:min(68cqw,68cqh);height:min(68cqw,68cqh)}.radar[data-el="meridian-deck-radar"]>.series>.name{top:0;left:var(--gap-sm)}.radar[data-el="meridian-deck-radar"]>.series:nth-child(2 of .series)>.name{left:35%}.radar[data-el="meridian-deck-radar"]>.series:nth-child(3 of .series)>.name{left:70%}\n''';f.write_text(s)
f=P/'slope/element.css';s=f.read_text()+'''\n.slope[data-el="meridian-deck-slope"]>.pair{container-type:size}.slope:not(.dumbbell)[data-el="meridian-deck-slope"]>.pair::before{width:hypot(100cqw,calc((var(--b) - var(--a))/var(--max)*100cqh));rotate:atan2(calc((var(--a) - var(--b))/var(--max)*100cqh),100cqw)}.slope:not(.dumbbell)[data-el="meridian-deck-slope"]>.pair>.name{left:auto;right:calc(100% + var(--gap));width:30cqw}\n''';f.write_text(s)
f=P/'sankey/element.css';f.write_text(f.read_text()+'''\n.sankey[data-el="meridian-deck-sankey"]>.source{top:var(--gap-sm);bottom:var(--gap-sm)}\n''')
f=P/'cycle/element.css';s=f.read_text()+'''\n.cycle[data-el="meridian-deck-cycle"]::before{inset:auto;left:50%;top:50%;translate:-50% -50%;width:min(66cqw,66cqh);height:min(66cqw,66cqh);border-radius:999px}.cycle[data-el="meridian-deck-cycle"]>.node{left:calc(50% + cos(-90deg + var(--meridian-deck-i)*360deg/var(--meridian-deck-nodecount))*min(33cqw,33cqh));top:calc(50% + sin(-90deg + var(--meridian-deck-i)*360deg/var(--meridian-deck-nodecount))*min(33cqw,33cqh));width:min(24cqw,26cqh);height:min(24cqw,26cqh)}.cycle[data-el="meridian-deck-cycle"]>.core{left:50%;right:auto;top:50%;translate:-50% -50%;width:min(26cqw,26cqh);height:min(26cqw,26cqh)}\n''';f.write_text(s)
